import {escape as e} from './workspace-shared.js';
const labels={unobserved:'Not enough evidence',beginning:'Beginning',developing:'Developing',secure:'Secure',extending:'Extending'};
export function liveBoardEvidenceHTML(records,{classId,learnerId='',students=[],unavailable=false}={}){
 const rows=records.filter(r=>!learnerId||r.learnerId===learnerId).sort((a,b)=>b.publishedAt-a.publishedAt);
 return `<section class="assessment-card live-board-evidence"><h2>Live Board assessments</h2><p class="assessment-footnote">Teacher-confirmed formative judgments with preserved evidence. These are separate from practice accuracy.</p>${unavailable?'<p role="status">Live Board assessments could not load. Refresh to try again.</p>':!rows.length?'<p>No published Live Board assessments yet.</p>':rows.map(r=>{const names=r.template==='story-mountain'?{sequence:'Plot and sequence',reasoning:'Stage reasoning',evidence:'Textual evidence',character:'Character response and change'}:{sequence:'Organization of ideas',reasoning:'Reasoning and justification',evidence:'Relevant evidence',character:'Reflection and transfer'};return `<details class="assessment-lesson"><summary>${learnerId?'':e(students.find(s=>s.id===r.learnerId)?.name||'Student')+' · '}${e(r.title)}<small>${e(new Date(r.publishedAt).toLocaleDateString())}</small></summary><div class="live-board-judgments">${Object.entries(names).map(([id,name])=>`<span><strong>${name}</strong>${e(labels[r.ratings[id]]||labels.unobserved)}</span>`).join('')}</div><p>${e(r.support==='supported'?'Supported':r.support==='independent'?'Independent':'Support not recorded')}</p>${r.feedback?`<p>${e(r.feedback)}</p>`:''}${r.standards?.length?`<p>${r.standards.map(s=>e(s.code)+': '+e(s.description)).join('<br>')}</p>`:''}${r.evidence.map(p=>`<blockquote><strong>${e(p.title||'Saved response')}</strong><p>${e(p.text)}</p>${[p.evidence,p.reference,p.reasoning,p.character].filter(Boolean).map(value=>`<p>${e(value)}</p>`).join('')}</blockquote>`).join('')}${r.reflection?`<blockquote><strong>Individual exit response</strong><p>${e(r.reflection)}</p></blockquote>`:''}<a class="teacher-button secondary" href="/notebooks?${new URLSearchParams({classId,notebookId:classId+'.boards',sectionId:'boards',pageId:r.boardId})}">Open activity ↗</a>${learnerId?'':`<button type="button" class="teacher-button secondary" data-assessment-learner="${e(r.learnerId)}">Open student profile</button>`}</details>`;}).join('')}</section>`;
}
